// Das Formular benennt die Binaerdatei nach dem Feldnamen.
// Whisper erwartet sie unter "data" — hier robust umbenennen.
const keys = Object.keys($input.item.binary || {});
if (keys.length === 0) {
  throw new Error('Keine Sprachnotiz im Upload gefunden.');
}
return {
  json: $input.item.json,
  binary: { data: $input.item.binary[keys[0]] }
};

// Zaehlt die vier vorab festgelegten Freigabekriterien aus
// docs/strategy/2026-08-01-lean-canvas-fermi.md, Teil 5.

const rows = $input.all().map(i => i.json).filter(r => r && r['Unternehmen']);
const t = v => (v === null || v === undefined ? '' : String(v)).trim();
const ja = v => t(v).toLowerCase() === 'ja';

const problem = rows.filter(r => t(r['Gespraechstyp']).startsWith('Problem'));
const partner = rows.filter(r => t(r['Gespraechstyp']).startsWith('Partner'));

const mehrfach   = problem.filter(r => ja(r['Mehrfachregulierung genannt'])).length;
const budgetHoch = rows.filter(r => ['25-70k', 'ueber 70k'].includes(t(r['Budget Signal']))).length;
const lieferant  = rows.filter(r => ja(r['Lieferantenrisiko'])).length;
const kaufgrund  = rows.filter(r => t(r['Herkunftsnachweis']) === 'Kaufgrund').length;
const gepitcht   = rows.filter(r => ja(r['Pitch gehalten'])).length;

const kriterien = [
  { name: 'PROBLEM — Mehrfachregulierung unaufgefordert', ist: mehrfach,        soll: 6, bezug: problem.length + ' Problem-Gespraeche' },
  { name: 'PREIS — Budgetsignal ueber 25k',               ist: budgetHoch,      soll: 3, bezug: rows.length + ' Gespraeche' },
  { name: 'PARTNER — Partnergespraeche (Risiko 1)',       ist: partner.length,  soll: 1, bezug: '90-Tage-Tor' },
  { name: 'LIEFERANTENRISIKO — Beschaffbarkeit',          ist: lieferant,       soll: 1, bezug: rows.length + ' Gespraeche' }
];

const kaeufer = {};
rows.forEach(r => {
  const k = t(r['Wirtschaftlicher Kaeufer']) || 'unklar';
  kaeufer[k] = (kaeufer[k] || 0) + 1;
});

const zitate = rows
  .map(r => t(r['Zitierfaehige Saetze']))
  .filter(z => z && z !== 'nicht genannt')
  .slice(-5);

const zeile = k => {
  const ok = k.ist >= k.soll;
  return '<tr><td>' + (ok ? '✅' : '⬜') + '</td><td>' + k.name + '</td>'
       + '<td align="right"><b>' + k.ist + '</b> / ' + k.soll + '</td>'
       + '<td>' + k.bezug + '</td></tr>';
};

const erfuellt = kriterien.filter(k => k.ist >= k.soll).length;

const html =
  '<h2>Running Lean — Stand nach ' + rows.length + ' Gespraechen</h2>' +
  '<p><b>' + erfuellt + ' von 4</b> Freigabekriterien erfuellt.</p>' +
  '<table cellpadding="6" border="1" style="border-collapse:collapse">' +
  '<tr><th></th><th align="left">Kriterium</th><th>Ist / Soll</th><th align="left">Bezug</th></tr>' +
  kriterien.map(zeile).join('') +
  '</table>' +
  '<h3>Selbstkontrolle</h3>' +
  '<p>In <b>' + gepitcht + ' von ' + rows.length + '</b> Gespraechen wurde die eigene Loesung praesentiert. ' +
  'In der Problem-Phase soll dieser Wert bei 0 liegen.</p>' +
  '<p>Herkunftsnachweis als Kaufgrund genannt: <b>' + kaufgrund + '</b></p>' +
  '<h3>Wer entscheidet ueber das Budget</h3><ul>' +
  Object.keys(kaeufer).map(k => '<li>' + k + ': ' + kaeufer[k] + '</li>').join('') +
  '</ul>' +
  '<h3>Zuletzt zitierfaehig (Material fuer das Angebot)</h3><ul>' +
  (zitate.length ? zitate.map(z => '<li><i>' + z + '</i></li>').join('') : '<li>noch keine</li>') +
  '</ul>' +
  '<hr><p style="color:#666">Messlatte aus docs/strategy/2026-08-01-lean-canvas-fermi.md, Teil 5. ' +
  'Werden die Kriterien nach 90 Tagen verfehlt, wird das Primaermodell gekippt — nicht die Messlatte.</p>';

return [{ json: { html, gespraeche: rows.length, erfuellt, gepitcht } }];
